// ================= Ready: a server on a free port and a client =================
type Client = tokio_tungstenite::WebSocketStream<tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>>;

async fn serve(app: Router) -> std::net::SocketAddr {
